,"product_id":"3d805548-7c4b-949b-8922-3e59ca73b1c1"},{"id":"1c0f1cb7-45f6-cd11-ca34-4b96c6b02fb8","product_id":"3d805548-7c4b-949b-8922-3e59ca73b1c1"},{"id":"a494039d-daf0-730d-0590-bc81ffe71c3d","product_id":"3d805548-7c4b-949b-8922-3e59ca73b1c1"},{"id":"f1df2b53-0ad9-109a-f835-40319f5a1944","product_id":"3d805548-7c4b-949b-8922-3e59ca73b1c1"},{"id":"5405b1cf-c49d-610f-2328-de0c2ca64d06","product_id":"3d805548-7c4b-949b-8922-3e59ca73b1c1"},{"id":"674d209d-09eb-5960-caf1-e1a8db1a0862","product_id":"3d805548-7c4b-949b-8922-3e59ca73b1c1"},{"id":"fc5448e0-9c03-afc0-e4c5-228c9fb60920","product_id":"3d805548-7c4b-949b-8922-3e59ca73b1c1"},{"id":"3402172e-5ded-3a2c-463c-ca2b520404a9","product_id":"3d805548-7c4b-949b-8922-3e59ca73b1c1"},{"id":"1a372415-6067-1c14-d409-4c1080b27cee","product_id":"be4c0686-4506-4b1c-c4e5-a8bdb8105c87"},{"id":"1750c6a5-a9d3-62a7-1ba0-be3afc8b4f08","product_id":"be4c0686-4506-4b1c-c4e5-a8bdb8105c87"},{"id":"5f721f4b-fcd6-172a-7f4a-2bb7bb336744","product_id":"be4c0686-4506-4b1c-c4e5-a8bdb8105c87"},{"id":"ef15cb9b-eb0b-0adf-0971-cf87b10d9df6","product_id":"be4c0686-4506-4b1c-c4e5-a8bdb8105c87"},{"id":"9a4ec00e-1b43-c172-1ebb-20050cdb1a92","product_id":"be4c0686-4506-4b1c-c4e5-a8bdb8105c87"},{"id":"a5536aec-ec7e-97f6-e176-96b78b94c299","product_id":"be4c0686-4506-4b1c-c4e5-a8bdb8105c87"},{"id":"5a383783-ae68-d42b-a618-de5d1f1e443e","product_id":"be4c0686-4506-4b1c-c4e5-a8bdb8105c87"},{"id":"8fce0f46-7cfa-6203-4c4a-269f195509e9","product_id":"be4c0686-4506-4b1c-c4e5-a8bdb8105c87"},{"id":"5952d963-4ebd-1149-e2b3-baa12760eb47","product_id":"d07af362-15e2-07a1-92db-590b75aa612b"},{"id":"5afee873-2310-95af-c315-3e20646228ad","product_id":"d07af362-15e2-07a1-92db-590b75aa612b"},{"id":"5b1e51d2-25e3-d124-46b3-308e299d65ac","product_id":"d07af362-15e2-07a1-92db-590b75aa612b"},{"id":"b17eecd0-2025-0831-cebd-733ac9f374e4","product_id":"d07af362-15e2-07a1-92db-590b75aa612b"},{"id":"5bba604b-3880-d64c-9e06-f68b2900b678","product_id":"d07af362-15e2-07a1-92db-590b75aa612b"},{"id":"6ff20152-44c1-ddc6-d8b6-c9212d687f66","product_id":"d07af362-15e2-07a1-92db-590b75aa612b"},{"id":"16c143f6-d15a-0a3f-3997-a5454969b5d9","product_id":"d07af362-15e2-07a1-92db-590b75aa612b"},{"id":"da93713b-2b8e-8ae7-5bec-67bc313787c6","product_id":"d07af362-15e2-07a1-92db-590b75aa612b"}]'::jsonb;
  base_images constant jsonb := '[{"id":"9b4988f5-3a9c-dd7f-1e87-cb97164ef0c9","product_id":"b932484c-98fb-f6a4-4bf3-b4131a97fd10","storage_path":"vanta-demo-v1/remera-essential/front.png"},{"id":"4f35d48d-1b96-f0d8-14e2-dfe7cc5c0491","product_id":"a407d197-84d3-02f7-d5bb-10cea8e7483a","storage_path":"vanta-demo-v1/remera-box/front.png"},{"id":"33479b90-2bac-d6b4-66d7-d18f4bc632f5","product_id":"287d20bb-02b0-7abf-1ed1-5faeb2bde79d","storage_path":"vanta-demo-v1/buzo-core/front.png"},{"id":"95362df5-2c4e-56a8-7558-827d610597cc","product_id":"592bb001-2877-5fba-c58f-8f9dd7befd29","storage_path":"vanta-demo-v1/buzo-relax/front.png"},{"id":"86d41b5e-adff-c98f-bafe-b5aa20ebdfc9","product_id":"5361ea09-80a3-470e-93c6-8de3e87c4ee8","storage_path":"vanta-demo-v1/pantalon-forma/front.png"},{"id":"7adfa83a-0478-32aa-2f37-4f710ba0fb28","product_id":"3d805548-7c4b-949b-8922-3e59ca73b1c1","storage_path":"vanta-demo-v1/pantalon-cargo/front.png"},{"id":"e76acf04-c9ad-091a-1bc7-96c611e75633","product_id":"be4c0686-4506-4b1c-c4e5-a8bdb8105c87","storage_path":"vanta-demo-v1/conjunto-studio/front.png"},{"id":"8a41d347-529d-b19d-1bd4-a0b1f7039e29","product_id":"d07af362-15e2-07a1-92db-590b75aa612b","storage_path":"vanta-demo-v1/conjunto-weekend/front.png"}]'::jsonb;
begin
  if confirmed_project_ref <> 'evlbfjvvljbkntlozokt' then
    raise exception 'Falta confirmar el proyecto VANTA: generar el archivo con --confirm-project=evlbfjvvljbkntlozokt --output=work/vanta-demo-load.sql';
  end if;
  -- This acknowledgement is NOT proof of database identity; verify Dashboard first.
  if not exists(select 1 from storage.buckets where id='product-images' and not public
    and file_size_limit=5242880 and 'image/png'=any(allowed_mime_types)) then
    raise exception 'Bucket privado incompatible; no se modifica su configuración';
  end if;
  lock table public.categories, public.products, public.product_variants,
    public.product_images, public.inventory in share row exclusive mode;

  -- Read-only prerequisites for the eight original models; never update/recreate them.
  if (select count(*) from jsonb_to_recordset(base_products) d(id uuid,slug text,category_slug text)
      join public.products p on p.id=d.id and p.slug=d.slug and p.active
      join public.categories c on c.id=p.category_id and c.slug=d.category_slug and c.active) <> 8
    or (select count(*) from jsonb_to_recordset(base_variants) d(id uuid,product_id uuid)
      join public.product_variants v on v.id=d.id and v.product_id=d.product_id) <> 64
    or (select count(*) from jsonb_to_recordset(base_images) d(id uuid,product_id uuid,storage_path text)
      join public.product_images i on i.id=d.id and i.product_id=d.product_id and i.storage_path=d.storage_path
      where exists(select 1 from storage.objects o where o.bucket_id='product-images' and o.name=d.storage_path)) <> 8
    or (select count(*) from jsonb_to_recordset(base_variants) d(id uuid,product_id uuid)
      join public.inventory i on i.variant_id=d.id) <> 64 then
    raise exception 'La ampliación requiere el catálogo inicial completo: 8 productos, 64 variantes/inventarios y 8 fotos. No se recrean ni modifican.';
  end if;
  if exists(select 1 from jsonb_to_recordset(demo_images) as d(id uuid,product_id uuid,storage_path text,alt text,position integer) where not exists(
    select 1 from storage.objects o where o.bucket_id='product-images' and o.name=d.storage_path)) then
    raise exception 'Faltan fotografías en Storage: se esperan rutas vanta-demo-v1 o vanta-demo-v2/<modelo>/front.png';
  end if;

  insert into public.categories(id,name,slug,active)
  select id,name,slug,true from jsonb_to_recordset(demo_categories) as d(id uuid,name text,slug text) on conflict do nothing;
  if (select count(*) from jsonb_to_recordset(demo_categories) as d(id uuid,name text,slug text) join public.categories c
    on c.slug=d.slug and c.name=d.name and c.active) <> 4 then
    raise exception 'Colisión o categoría inactiva: no se sobrescriben categorías existentes';
  end if;

  insert into public.products(id,category_id,name,slug,description,price_cents,currency,active)
  select d.id,c.id,d.name,d.slug,d.description,d.price_cents,'ARS',true
  from jsonb_to_recordset(demo_products) as d(id uuid,category_slug text,name text,slug text,description text,price_cents bigint) join public.categories c on c.slug=d.category_slug
  on conflict do nothing;
  if (select count(*) from jsonb_to_recordset(demo_products) as d(id uuid,category_slug text,name text,slug text,description text,price_cents bigint) join public.categories c on c.slug=d.category_slug
    join public.products p on p.id=d.id and p.slug=d.slug and p.category_id=c.id
      and p.name=d.name and p.description=d.description and p.price_cents=d.price_cents and p.currency='ARS' and p.active) <> 4 then
    raise exception 'Colisión o producto demo alterado: transacción cancelada sin sobrescribir';
  end if;

  insert into public.product_variants(id,product_id,sku,size,color,active)
  select id,product_id,sku,size,color,true from jsonb_to_recordset(demo_variants) as d(id uuid,product_id uuid,sku text,size text,color text) on conflict do nothing;
  if (select count(*) from jsonb_to_recordset(demo_variants) as d(id uuid,product_id uuid,sku text,size text,color text) join public.product_variants v
    on v.id=d.id and v.product_id=d.product_id and v.sku=d.sku and v.size=d.size and v.color=d.color and v.active) <> 32 then
    raise exception 'Colisión o variante demo alterada: transacción cancelada';
  end if;

  insert into public.product_images(id,product_id,storage_path,alt,position)
  select id,product_id,storage_path,alt,position from jsonb_to_recordset(demo_images) as d(id uuid,product_id uuid,storage_path text,alt text,position integer) on conflict do nothing;
  if (select count(*) from jsonb_to_recordset(demo_images) as d(id uuid,product_id uuid,storage_path text,alt text,position integer) join public.product_images i
    on i.id=d.id and i.product_id=d.product_id and i.storage_path=d.storage_path and i.alt=d.alt and i.position=d.position) <> 4 then
    raise exception 'Colisión o imagen demo alterada: transacción cancelada';
  end if;

  -- Never restock existing rows or reset reservations on repetition.
  insert into public.inventory(variant_id,on_hand,reserved)
  select id,6,0 from jsonb_to_recordset(demo_variants) as d(id uuid,product_id uuid,sku text,size text,color text) on conflict (variant_id) do nothing;
end
$vanta_demo$;

-- Independent read-only summary: no temporary or session state.
with demo_products(id) as (select unnest(array['09931042-6f06-2b70-d51f-9e51e751437b'::uuid,'4a18127e-1b37-4df1-3e3a-761b8b07d571'::uuid,'8d1d1927-9282-e90e-c6ab-4a999eeed79f'::uuid,'eea7c91d-0da9-b2d1-ce41-58a01fb49d6e'::uuid])), catalog_products(id) as (select unnest(array['b932484c-98fb-f6a4-4bf3-b4131a97fd10'::uuid,'a407d197-84d3-02f7-d5bb-10cea8e7483a'::uuid,'287d20bb-02b0-7abf-1ed1-5faeb2bde79d'::uuid,'592bb001-2877-5fba-c58f-8f9dd7befd29'::uuid,'5361ea09-80a3-470e-93c6-8de3e87c4ee8'::uuid,'3d805548-7c4b-949b-8922-3e59ca73b1c1'::uuid,'be4c0686-4506-4b1c-c4e5-a8bdb8105c87'::uuid,'d07af362-15e2-07a1-92db-590b75aa612b'::uuid,'09931042-6f06-2b70-d51f-9e51e751437b'::uuid,'4a18127e-1b37-4df1-3e3a-761b8b07d571'::uuid,'8d1d1927-9282-e90e-c6ab-4a999eeed79f'::uuid,'eea7c91d-0da9-b2d1-ce41-58a01fb49d6e'::uuid]))
select
  (select count(*) from public.products p join demo_products d on p.id=d.id) as demo_products,
  (select count(*) from public.product_variants v join demo_products d on v.product_id=d.id) as demo_variants,
  (select count(*) from public.product_images i join demo_products d on i.product_id=d.id) as demo_images,
  (select count(*) from public.inventory i join public.product_variants v on v.id=i.variant_id
    join demo_products d on v.product_id=d.id) as demo_inventory_rows,
  (select count(*) from public.products p join catalog_products d on p.id=d.id) as catalog_products,
  (select count(*) from public.product_variants v join catalog_products d on v.product_id=d.id) as catalog_variants,
  (select count(*) from public.product_images i join catalog_products d on i.product_id=d.id) as catalog_images,
  (select count(*) from public.inventory i join public.product_variants v on v.id=i.variant_id
    join catalog_products d on v.product_id=d.id) as catalog_inventory_rows;
